import { createAppAuth } from "@octokit/auth-app";

// Never "workflows": without it, GitHub refuses any push that changes .github/workflows/.
const WRITE_PERMISSIONS = { contents: "write", pull_requests: "write", checks: "read", actions: "read" };
const auth = createAppAuth({ appId: config.githubAppId, privateKey: config.githubAppPrivateKey });

export const mintToken = async (scope: RunScope): Promise<string> => {
  const { token } = await auth({
    type: "installation",
    installationId: config.installationId,
    repositoryNames: [scope.repo.split("/")[1]],
    permissions: WRITE_PERMISSIONS,
  });
  return token; // valid for one hour; it never leaves the broker
};

