cat > mint.mjs <<'EOF'
// Step 1 of every GitHub App call: prove you are the App with a JWT signed by its private key.
// Step 2: trade that JWT for an installation token, narrowed to one repo and a few permissions.
import { readFileSync } from "node:fs";
import { createSign, createVerify, createPublicKey } from "node:crypto";
import { endpoint } from "@octokit/endpoint";

const APP_ID = "123456";             // a made-up App; GitHub shows the real one on the App's page
const INSTALLATION_ID = 98765432;    // one installation = the App on one org's chosen repos
const privateKey = readFileSync("test-app.pem", "utf8");

const b64url = (obj) => Buffer.from(JSON.stringify(obj)).toString("base64url");
const now = Math.floor(Date.now() / 1000);
const header = b64url({ alg: "RS256", typ: "JWT" });
const payload = b64url({ iat: now - 60, exp: now + 9 * 60, iss: APP_ID });
const signature = createSign("RSA-SHA256").update(`${header}.${payload}`).sign(privateKey, "base64url");
const jwt = `${header}.${payload}.${signature}`;

console.log("JWT payload:", JSON.parse(Buffer.from(payload, "base64url")));
const publicKey = createPublicKey(privateKey); // GitHub keeps only this half
console.log("GitHub can verify it:", createVerify("RSA-SHA256").update(`${header}.${payload}`).verify(publicKey, signature, "base64url"));

const exchange = endpoint("POST /app/installations/{installation_id}/access_tokens", {
  installation_id: INSTALLATION_ID,
  headers: { authorization: `Bearer ${jwt.slice(0, 12)}…` },
  repositories: ["fcp"],
  permissions: { contents: "write", pull_requests: "write" },
});
console.log("The exchange request:", exchange.method, exchange.url);
console.log("Its body:", JSON.stringify(exchange.body));
EOF
