// Return { ok, reason }: what main's ruleset says about merging this pull request.
const PASSING = ["success", "skipped", "neutral"];

export const canMerge = (rules, pr) => {
  for (const rule of rules) {
    const p = rule.parameters;
    if (rule.type === "pull_request") {
      const approvals = pr.reviews.filter((r) =>
        r.state === "APPROVED"
        && (!p.dismiss_stale_reviews_on_push || r.commit === pr.head)
        && (!p.require_last_push_approval || r.user !== pr.lastPusher));
      if (approvals.length < p.required_approving_review_count)
        return { ok: false, reason: `needs ${p.required_approving_review_count} approval, has ${approvals.length}` };
    }
    if (rule.type === "required_status_checks") {
      for (const { context } of p.required_status_checks) {
        const result = pr.checks[context];
        if (!result) return { ok: false, reason: `waiting for "${context}"` };
        if (!PASSING.includes(result)) return { ok: false, reason: `"${context}" is ${result}` };
      }
    }
  }
  return { ok: true, reason: "all rules pass" };
};
